insert into public.pages (slug,title,excerpt,meta_description,content,published,sort_order)
values ('sobre','Sobre Mim / Sobre o Blog','Conheça Jessica Silva Salgado e a proposta do blog Physio to PhD.','Conheça Jessica Silva Salgado e a proposta do blog Physio to PhD.','<p>Bem-vindo(a)!</p><p>Meu nome é <strong>Jessica Silva Salgado</strong> e este blog nasceu da paixão pela <strong>fisioterapia, neurociência, pesquisa científica e inovação em reabilitação</strong>.</p><p>Sou fisioterapeuta em formação no Brasil e futura pesquisadora, com foco em <strong>neuroreabilitação, controle motor, aprendizagem motora e tecnologias aplicadas ao movimento humano</strong>. Meu objetivo é contribuir para uma fisioterapia cada vez mais baseada em evidências, conectando a prática clínica aos avanços da ciência.</p><h2>O que você encontrará aqui</h2><p>Este é um espaço dedicado à divulgação de conhecimento científico de forma clara, confiável e acessível. Os conteúdos abordam temas como:</p><ul><li><p>Neuroplasticidade e neuroreabilitação;</p></li><li><p>Fisioterapia baseada em evidências;</p></li><li><p>Realidade virtual, inteligência artificial, robótica e outras tecnologias na reabilitação;</p></li><li><p>Transtornos neurológicos e desenvolvimento motor;</p></li><li><p>Resumos e análises de artigos científicos;</p></li><li><p>Ferramentas para estudantes e pesquisadores;</p></li><li><p>Minha jornada rumo ao Ph.D. nos Estados Unidos, incluindo preparação para o TOEFL, pesquisa acadêmica e processo de candidatura.</p></li></ul><h2>Minha missão</h2><p>Acredito que a ciência deve estar ao alcance de todos. Por isso, meu compromisso é transformar pesquisas complexas em conteúdos práticos, atualizados e úteis para estudantes, fisioterapeutas, pesquisadores e profissionais da saúde.</p><p>Também desejo inspirar outros brasileiros que sonham em construir uma carreira acadêmica internacional, mostrando os desafios, aprendizados e conquistas ao longo desse caminho.</p><h2>Para quem é este blog?</h2><p>Este conteúdo foi criado para:</p><ul><li><p>Estudantes de Fisioterapia;</p></li><li><p>Fisioterapeutas e profissionais da saúde;</p></li><li><p>Pesquisadores e pós-graduandos;</p></li><li><p>Pessoas interessadas em neurociência e reabilitação;</p></li><li><p>Quem deseja acompanhar a evolução das tecnologias aplicadas à saúde.</p></li></ul><h2>Vamos aprender juntos?</h2><p>A ciência está em constante evolução, e este blog acompanhará esse movimento. Novos artigos, revisões científicas e conteúdos exclusivos serão publicados regularmente para compartilhar conhecimento e discutir as principais tendências da fisioterapia e da neuroreabilitação.</p><p>Obrigado por visitar este espaço. Espero que os conteúdos contribuam para sua formação, inspirem novas ideias e despertem ainda mais interesse pela ciência.</p><p><strong>Seja muito bem-vindo(a)!</strong></p>',true,10)
on conflict (slug) do update set title=excluded.title, excerpt=excluded.excerpt, meta_description=excluded.meta_description, content=excluded.content, published=true, sort_order=excluded.sort_order;
insert into public.pages (slug,title,excerpt,meta_description,content,published,sort_order)
values ('contato','Contato','Fale comigo sobre pesquisa, parcerias e divulgação científica.','Fale comigo sobre pesquisa, parcerias e divulgação científica.','<p>Obrigado por visitar o blog!</p><p>Se você tiver dúvidas, sugestões, interesse em parcerias, oportunidades de pesquisa ou simplesmente quiser conversar sobre fisioterapia, neuroreabilitação, tecnologia aplicada à saúde ou carreira acadêmica internacional, ficarei feliz em receber sua mensagem.</p><h2>E-mail</h2><p>📧 <strong><a href="mailto:jessicass2485@gmail.com">jessicass2485@gmail.com</a></strong></p><h2>LinkedIn</h2><p>🔗 <strong>Jessica Silva Salgado</strong><br><a href="https://www.linkedin.com/in/jessicasilvasalgado/">https://www.linkedin.com/in/jessicasilvasalgado/</a></p><h2>Instagram</h2><p>📷 <strong>@jeeh_ssalgado</strong><br><a href="https://www.instagram.com/jeeh_ssalgado/">https://www.instagram.com/jeeh_ssalgado/</a></p><h2>Parcerias</h2><p>Estou aberta a oportunidades de:</p><ul><li><p>Colaboração em projetos de pesquisa;</p></li><li><p>Divulgação científica;</p></li><li><p>Networking acadêmico;</p></li><li><p>Parcerias com instituições de ensino e pesquisa;</p></li><li><p>Eventos, palestras e produção de conteúdo.</p></li></ul><p><strong>Responderei às mensagens o mais breve possível.</strong></p><p>Obrigado pelo contato!</p><div><iframe frameborder="0" height="900" marginheight="0" marginwidth="0" src="https://docs.google.com/forms/d/e/1FAIpQLSe_CJN98-W5uE5HG633BHl0WjNVm45nCiLIRoVT_H9tiOeZ2A/viewform?embedded=true" width="640">Carregando&#8230;</iframe></div>',true,20)
